with kept_keys as (select customer_id from sessions intersect all select customer_id from sessions where browser in ('Chrome', 'Firefox')), kept_rows as (select s.* from sessions s inner join kept_keys k on s.customer_id = k.customer_id) select id, customer_id, device, browser, started_at, country, case when device rlike '^(desktop|tablet)$' then 'CORE' else 'GROUP_A' end as device_zone from kept_rows order by device_zone desc, customer_id
